  function basicWeaknessPoolForDeck(metadata, lookupTables, settings, deck, options = {}) {
    const factionCode = deck.investigatorBack.card.faction_code;
    const requiredTraits = options.requiredTraits ?? [];
    const limitedPool = resolveLimitedPoolPacks(
      metadata,
      deck.cardPool ?? []
    ).map((p) => p.code);
    const ignoreDeckCardPool = options.ignoreDeckCardPool ?? !settings.useLimitedPoolForWeaknessDraw;
    const useLimitedPool = !ignoreDeckCardPool && !isEmpty(limitedPool);
    const collection = useLimitedPool ? limitedPool.reduce((acc, curr) => {
      acc[curr] = settings.collection?.[curr] || 1;
      return acc;
    }, {}) : settings.collection;
    const basicWeaknesses = Object.keys(
      lookupTables.subtypeCode["basicweakness"]
    ).reduce((acc, code) => {
      const card = metadata.cards[code];
      const opts = {
        metadata,
        lookupTables,
        collection,
        showAllCards: !useLimitedPool && settings.showAllCards,
        strict: useLimitedPool || settings.cardListsDefaultContentType === "official"
      };
      const ownedCount = ownedCardCount({
        card,
        ...opts
      });
      if (card.code === SPECIAL_CARD_CODES.RANDOM_BASIC_WEAKNESS || !!card.duplicate_of_code || ownedCount === 0 || deck.slots[code] >= cardLimit(card) || requiredTraits.length > 0 && !splitMultiValue(card.real_traits).some(
        (trait) => requiredTraits.includes(trait)
      )) {
        return acc;
      }
      if (card.reprint_of) {
        const reprinted = metadata.cards[card.reprint_of];
        const ownedBase = ownedCardCount({
          card: reprinted,
          ...opts
        });
        if (ownedBase > 0) return acc;
      }
      if (card.restrictions?.faction && !card.restrictions.faction.includes(factionCode)) {
        return acc;
      }
      const availableCopies = Math.min(ownedCount, card.deck_limit ?? 0);
      const codes = Array.from(
        {
          length: options.equalProbability ? Math.min(availableCopies, 1) : availableCopies
        },
        () => code
      );
      acc.push(...codes);
      return acc;
    }, []);
    return basicWeaknesses;
  }

